import unittest
from toy import add_int

class ToyTests(unittest.TestCase):
    def test_add(self):
        self.assertEqual(add_int(2, 3), 5)
        self.assertEqual(add_int(4, 1), 5)

    def test_invalid_type(self):
        with self.assertRaises(TypeError):
            add_int("2", 3)

